<?php
// Storage compatibility and the configured deadline editor/detail view.
ob_start(); require __DIR__ . '/initiatives.php'; $baselineOutput = ob_get_clean();
ob_start(); $baselineChecks = $checks;
loadIsolated('php/DeadlineForms.php');
$osiris->deadlines = new MemoryCollection();
$fields = DeadlineForms::fields($osiris);
check(array_column($fields, 'id') === ['deadline-title', 'deadline-date', 'deadline-type', 'deadline-description', 'url'], 'The default keeps the previous deadline fields and order.');
$config = DeadlineForms::builder();
check(isset($config->modules['persons'], $config->modules['initiatives'], $config->modules['objectives']) && !isset($config->modules['date-range'], $config->modules['event-public']), 'Deadlines offer suitable associations without event-specific fields.');
rejects(fn() => FormBuilder::validateFields([], DeadlineForms::SYSTEM_FIELDS), 'Required system fields cannot be removed.');
$type = (new Vocabulary())->getValues('deadline-type')[0]['id'];
$input = ['title' => 'Call for papers', 'date' => '2026-11-30', 'type' => $type, 'description' => '<p>A deadline</p>', 'url' => 'https://example.org', 'roles' => ['scientist' => '1'], 'created_by' => 'forged', 'unconfigured' => 'ignored'];
$values = DeadlineForms::values($input, $osiris, $Settings);
check($values['date'] === $input['date'] && $values['year'] === 2026 && $values['month'] === 11 && $values['quarter'] === 4 && !isset($values['start']), 'The date remains an ISO string with compatible dashboard date fields.');
check($values['roles'] === ['scientist'] && !isset($values['created_by'], $values['unconfigured']), 'Audience roles remain separate from configured fields; metadata cannot be overwritten.');
check(DeadlineForms::values(array_replace($input, ['roles' => []]), $osiris, $Settings)['roles'] === ['user'], 'No selected audience retains the previous all-users default.');
rejects(fn() => DeadlineForms::values(array_replace($input, ['date' => '2026-02-30']), $osiris, $Settings), 'Invalid dates cannot be saved.');
rejects(fn() => DeadlineForms::values(array_replace($input, ['title' => '']), $osiris, $Settings), 'Empty system fields cannot be saved.');
$legacy = array_replace($input, ['type' => 'imported-type']);
check(DeadlineForms::values($legacy, $osiris, $Settings, $legacy)['type'] === 'imported-type', 'Existing imported types survive editing without allowing new unknown types.');
rejects(fn() => DeadlineForms::values($legacy, $osiris, $Settings), 'A new unknown type is rejected.');
$form = DeadlineForms::redisplay($input);
check($form['roles'] === ['scientist'], 'Validation errors retain checked audience roles.');
ob_start(); loadIsolated('pages/deadlines/edit.php'); $html = ob_get_clean();
check(str_contains($html, 'name="values[date]"') && str_contains($html, 'name="values[roles][scientist]" checked') && str_contains($html, "quillEditor('deadline-description')"), 'The editor renders configured inputs, rich text and the separate audience selector.');
$deadline = array_replace($values, ['_id' => new MongoDB\BSON\ObjectId(), 'created_by' => 'reviewer']);
$osiris->deadlines->insertOne($deadline);
$format = new Document(false, 'list');
check(str_contains($format->getDeadlineField($deadline, 'deadline-date'), '2026') && $format->getDeadlineField($deadline, 'deadline-description') === $input['description'], 'Document renders the original deadline date and formatted description.');
$source = file_get_contents(BASEPATH . '/routes/events.php');
$source = str_replace('include_once BASEPATH . "/php/init.php";', 'global $DB, $osiris, $Settings;', $source);
$source = preg_replace('/^\s*(?:include|require)(?:_once)? .*;\R/m', '', $source);
eval('?>' . $source);
$_POST = ['values' => $input];
$_SERVER['HTTP_ACCEPT'] = 'application/json';
ob_start(); Route::$routes['POST /crud/deadlines/add'][0](); $result = json_decode(ob_get_clean(), true);
check($result['status'] === 'warning' && $result['id'] === (string) $deadline['_id'], 'Duplicates are matched by title and date, without the obsolete start key.');
$save = Route::$routes['POST /crud/deadlines/update/(.*)'][0];
$_POST['values']['title'] = 'Updated deadline';
$save((string) $deadline['_id']);
check($osiris->deadlines->findOne(['_id' => $deadline['_id']])['title'] === 'Updated deadline', 'The actual save route uses the new form configuration.');
$osiris->deadlines->updateOne(['_id' => $deadline['_id']], ['$set' => ['created_by' => 'another-user']]);
aborts(fn() => $save((string) $deadline['_id']), 403);
$view = preg_replace('/^\s*(?:include|require)(?:_once)? .*;\R/m', '', file_get_contents(BASEPATH . '/pages/deadlines/view.php'));
ob_start(); eval('?>' . $view); $html = ob_get_clean();
check(str_contains($html, 'A deadline') && str_contains($html, '/deadline/ics/'), 'The detail view renders configured fields and retains calendar export.');
ob_end_clean(); echo $baselineOutput; echo 'Deadline form checks passed (' . ($checks - $baselineChecks) . " checks).\n";
